import React, { ReactElement } from "react";
import { DivFlexColumn, DivFlexRow, StyledLabel } from "./elements/formelements";
import TextInputWithIcon from "./TextInputWithIcon";

interface TextInputProps {
    label?: string;
    ariaLabel: string;
    value: string;
    onChange: (value: string) => void;
    placeholder?: string;
    readOnly?: boolean;
    icon?: ReactElement | string;
    validate?: () => string | true;
    description?: string;
}

const TextInputLabeled: React.FC<TextInputProps> = ({
    label,
    ariaLabel,
    value,
    onChange,
    placeholder,
    readOnly = false,
    icon,
    validate,
    description,
}) => {
    return (
        <DivFlexRow>
            {label && (
                <DivFlexColumn>
                    <StyledLabel>{label}</StyledLabel>
                </DivFlexColumn>
            )}
            <DivFlexColumn fullWidth>
                <TextInputWithIcon
                    ariaLabel={ariaLabel}
                    value={value}
                    onChange={onChange}
                    placeholder={placeholder}
                    readOnly={readOnly}
                    icon={icon}
                    validate={validate}
                    description={description}
                />
            </DivFlexColumn>
        </DivFlexRow>
    );
};

export default TextInputLabeled;
